#!/usr/bin/env python3
from __future__ import annotations
import json, re, html
from pathlib import Path
from collections import Counter
ROOT=Path(__file__).resolve().parents[2]; DATA=ROOT/'web/data'; IMG=ROOT/'web/images/people'
SOURCE_OCA='https://www.oca.org/fs'

# Load every existing dataset including the previous expansion.
files=['entries.js','expanded-biblical.js','church-saints.js','feasts.js','biblical-context.js','further-expansion.js']
all_entries=[]
for fn in files:
    p=DATA/fn
    all_entries.extend(json.loads(p.read_text(encoding='utf-8').split('=',1)[1].strip().rstrip(';')))
ids={e['id'] for e in all_entries}
more=[]

def mk(id,en,el,cat,ren,rel,sc='Church tradition / Lives of the Saints',feast='See local Orthodox calendar',v=True,source=SOURCE_OCA,story=None):
    if id in ids or any(x['id']==id for x in more): return
    if story is None:
        if cat=='biblical-context':
            story={'en':f'{en} is included as {ren.lower()} in the wider biblical record. This index-style entry helps make lesser-known names and beings searchable without presenting them as saints.',
                   'el':f'Ο/Η {el} περιλαμβάνεται ως {rel.lower()} στο ευρύτερο βιβλικό αρχείο. Η συνοπτική καταχώριση βοηθά να αναζητούνται λιγότερο γνωστά ονόματα και όντα χωρίς να παρουσιάζονται ως άγιοι.'}
        else:
            story={'en':f'{en} is honored in Orthodox tradition as {ren.lower()}. This compact record is designed for discovery; consult a synaxarion for a complete life and liturgical texts.',
                   'el':f'Ο/Η {el} τιμάται στην Ορθόδοξη παράδοση ως {rel.lower()}. Η συνοπτική καταχώριση προορίζεται για ανακάλυψη· για πλήρη βίο και λειτουργικά κείμενα συμβουλευτείτε συναξάρι.'}
    elif isinstance(story,str): story={'en':story,'el':'Σύντομη βιβλική και ορθόδοξη εκπαιδευτική καταχώριση.'}
    if cat=='biblical-context':
        prayer={'en':'Lord, grant me wisdom and discernment to read Scripture faithfully, reject evil, recognize Your providence, and follow what is good.', 'el':'Κύριε, δώσε μου σοφία και διάκριση να διαβάζω πιστά τη Γραφή, να απορρίπτω το κακό, να αναγνωρίζω την πρόνοιά Σου και να ακολουθώ το αγαθό.'}
        notes={'en':'Biblical-context entry; no prayer is addressed to this figure or symbol.', 'el':'Καταχώριση βιβλικού πλαισίου· δεν απευθύνεται προσευχή σε αυτό το πρόσωπο ή σύμβολο.'}
    else:
        prayer={'en':f'Holy {en}, pray to God for us and help us grow in faith, repentance, humility, courage, and love.', 'el':f'Άγιε/Αγία {el}, πρέσβευε στον Θεό για μας και βοήθησέ μας να αυξανόμαστε σε πίστη, μετάνοια, ταπείνωση, θάρρος και αγάπη.'}
        notes={'en':'Concise educational entry; feast dates may differ by local Orthodox calendar.', 'el':'Σύντομη εκπαιδευτική καταχώριση· οι ημερομηνίες μπορεί να διαφέρουν ανά τοπικό ορθόδοξο ημερολόγιο.'}
    e={'id':id,'name':{'en':en,'el':el},'category':cat,'role':{'en':ren,'el':rel},'story':story,'feast':{'en':feast,'el':feast},'scripture':sc,'prayer':prayer,'notes':notes,'aliases':[],'venerated':v,'image':f'web/images/people/{id}.svg','search':' '.join([en,el,ren,rel,sc])}
    if source: e.update(sourceUrl=source,sourceLabel='Orthodox calendar / reference')
    more.append(e)

