# Saint Apphia is venerated in Orthodox tradition with Philemon and Archippus.
for e in more:
    if e['id']=='apphia':
        e['category']='nt-saint'; e['venerated']=True; e['feast']={'en':'22 November','el':'22 November'}
        e['story']={'en':'Saint Apphia is greeted in the Letter to Philemon and is honored in Orthodox tradition together with Philemon and Archippus.','el':'Η Αγία Απφία χαιρετίζεται στην προς Φιλήμονα και τιμάται στην Ορθόδοξη παράδοση μαζί με τον Φιλήμονα και τον Άρχιππο.'}
        e['prayer']={'en':'Holy Saint Apphia, pray to God for us, that we may grow in faith, repentance, humility, courage, and love.','el':'Αγία Απφία, πρέσβευε στον Θεό για μας, ώστε να αυξανόμαστε σε πίστη, μετάνοια, ταπείνωση, θάρρος και αγάπη.'}
        e['notes']={'en':'Venerated in Orthodox tradition; consult a local synaxarion for fuller liturgical details.','el':'Τιμάται στην Ορθόδοξη παράδοση· συμβουλευτείτε τοπικό συναξάρι για πληρέστερες λειτουργικές λεπτομέρειες.'}
        e['sourceUrl']=SOURCE_OCA; e['sourceLabel']='Orthodox calendar / reference'

# Generate simple local SVGs for the new entries.
colors={'church-saint':('#ff9e6f','#50213b'),'nt-saint':('#79f0c8','#174844'),'biblical-context':('#aeb6d2','#25294a')}
for e in more:
    p=ROOT/e['image']
    if p.exists(): continue
    c1,c2=colors[e['category']]
    tokens=[w for w in re.findall(r'[A-Za-z]+',e['name']['en']) if w.lower() not in {'saint','saints','holy','the','of','and','in'}]
    letters=''.join(w[0] for w in tokens)[:3].upper() or '☦'
    svg=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 240 240" role="img" aria-label="{html.escape(e['name']['en'])}"><defs><radialGradient id="g"><stop offset="0" stop-color="{c1}"/><stop offset="1" stop-color="{c2}"/></radialGradient></defs><rect width="240" height="240" rx="120" fill="url(#g)"/><circle cx="120" cy="120" r="102" fill="none" stroke="#fff" stroke-opacity=".45" stroke-width="3"/><text x="120" y="35" text-anchor="middle" font-size="21" fill="#fff">☦</text><circle cx="120" cy="105" r="55" fill="#fff" fill-opacity=".1"/><text x="120" y="119" text-anchor="middle" font-family="Georgia,serif" font-size="43" font-weight="700" fill="#fff">{letters}</text><text x="120" y="208" text-anchor="middle" font-family="Arial,sans-serif" font-size="12" fill="#fff" fill-opacity=".78">ORTHODOX WEB</text></svg>'''
    p.write_text(svg,encoding='utf-8')

out=DATA/'deep-biblical.js'; out.write_text('window.ORTHODOX_DEEP_BIBLICAL = '+json.dumps(more,ensure_ascii=False,separators=(',',':'))+';\n',encoding='utf-8')
print('Added deep layer:',len(more)); print('New total:',len(all_entries)+len(more)); print(dict(sorted(Counter(e['category'] for e in all_entries+more).items())))
